[CmdletBinding()]
param()

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$script:ProjectRoot = Split-Path -Parent $PSScriptRoot
$script:RuntimeDir = Join-Path $script:ProjectRoot 'runtime'
$script:StateDir = Join-Path $script:RuntimeDir 'state'
$script:LogsDir = Join-Path $script:RuntimeDir 'logs'
$script:PidPath = Join-Path $script:StateDir 'worker.pid'
$script:LockPath = Join-Path $script:StateDir 'worker.lock'
$script:WorkerStatePath = Join-Path $script:StateDir 'worker-state.json'
$script:HeartbeatPath = Join-Path $script:StateDir 'heartbeat.local.json'
$script:StartWorkerCmd = Join-Path $script:ProjectRoot 'START_WORKER.cmd'

foreach ($dir in @($script:RuntimeDir, $script:StateDir, $script:LogsDir)) {
    if (-not (Test-Path -LiteralPath $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }
}

$script:LogFile = Join-Path $script:LogsDir ('bridge-start-{0}.log' -f (Get-Date -Format 'yyyyMMdd-HHmmss'))

function Write-BridgeLog {
    param(
        [Parameter(Mandatory = $true)]
        [string]$Message,
        [ValidateSet('INFO', 'WARN', 'ERROR')]
        [string]$Level = 'INFO'
    )

    $timestamp = Get-Date -Format 'yyyy-MM-dd HH:mm:ss'
    $line = '[{0}] [{1}] {2}' -f $timestamp, $Level, $Message
    Write-Host $line
    Add-Content -LiteralPath $script:LogFile -Value $line
}

function Get-TrimmedFileContent {
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path
    )

    if (-not (Test-Path -LiteralPath $Path)) {
        return $null
    }

    return (Get-Content -LiteralPath $Path -Raw).Trim()
}

function Read-JsonFile {
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path
    )

    if (-not (Test-Path -LiteralPath $Path)) {
        return $null
    }

    try {
        return Get-Content -LiteralPath $Path -Raw | ConvertFrom-Json
    }
    catch {
        return $null
    }
}

function ConvertTo-IntOrNull {
    param(
        [AllowNull()]
        [object]$Value
    )

    if ($null -eq $Value) {
        return $null
    }

    $text = [string]$Value
    $parsedValue = 0
    if ([int]::TryParse($text.Trim(), [ref]$parsedValue) -and $parsedValue -gt 0) {
        return $parsedValue
    }

    return $null
}

function Get-ObjectPropertyOrNull {
    param(
        [AllowNull()]
        [object]$Object,
        [Parameter(Mandatory = $true)]
        [string]$PropertyName
    )

    if ($null -eq $Object) {
        return $null
    }

    $property = $Object.PSObject.Properties[$PropertyName]
    if ($null -eq $property) {
        return $null
    }

    return $property.Value
}

function Get-JsonTimestampSnapshot {
    param(
        [Parameter(Mandatory = $true)]
        [string]$Path,
        [string]$TimestampProperty = 'updated_at',
        [string]$PidProperty = 'pid'
    )

    $snapshot = [ordered]@{
        Exists = Test-Path -LiteralPath $Path
        LastWriteTimeUtc = $null
        UpdatedAt = $null
        Pid = $null
    }

    if ($snapshot.Exists) {
        $item = Get-Item -LiteralPath $Path
        $snapshot.LastWriteTimeUtc = $item.LastWriteTimeUtc

        $data = Read-JsonFile -Path $Path
        if ($data) {
            if ($PidProperty) {
                $snapshot.Pid = ConvertTo-IntOrNull -Value $data.$PidProperty
            }

            $timestampValue = $data.$TimestampProperty
            if ($timestampValue) {
                try {
                    $snapshot.UpdatedAt = [DateTimeOffset]::Parse([string]$timestampValue)
                }
                catch {
                    $snapshot.UpdatedAt = $null
                }
            }
        }
    }

    return [pscustomobject]$snapshot
}

function Get-LiveProcessRecord {
    param(
        [Parameter(Mandatory = $true)]
        [int]$ProcessId
    )

    try {
        $process = Get-Process -Id $ProcessId -ErrorAction Stop
        if ($process.ProcessName -notin @('powershell', 'pwsh')) {
            return $null
        }

        return $process
    }
    catch {
        return $null
    }
}

function Get-WorkerStatus {
    $pidFileText = Get-TrimmedFileContent -Path $script:PidPath
    $lockData = Read-JsonFile -Path $script:LockPath
    $stateData = Read-JsonFile -Path $script:WorkerStatePath
    $heartbeatData = Read-JsonFile -Path $script:HeartbeatPath

    $pidFilePid = ConvertTo-IntOrNull -Value $pidFileText
    $lockPid = ConvertTo-IntOrNull -Value (Get-ObjectPropertyOrNull -Object $lockData -PropertyName 'pid')
    $statePid = ConvertTo-IntOrNull -Value (Get-ObjectPropertyOrNull -Object $stateData -PropertyName 'pid')
    $stateStatus = [string](Get-ObjectPropertyOrNull -Object $stateData -PropertyName 'status')
    $stateStatusMessage = [string](Get-ObjectPropertyOrNull -Object $stateData -PropertyName 'status_message')
    $stateLastStage = [string](Get-ObjectPropertyOrNull -Object $stateData -PropertyName 'last_stage')
    $heartbeatStatus = [string](Get-ObjectPropertyOrNull -Object $heartbeatData -PropertyName 'status')

    $candidateIds = @()
    foreach ($candidate in @($pidFilePid, $lockPid, $statePid)) {
        if ($candidate -and $candidate -notin $candidateIds) {
            $candidateIds += $candidate
        }
    }

    $liveCandidates = @(
        foreach ($candidateId in $candidateIds) {
            $process = Get-LiveProcessRecord -ProcessId $candidateId
            if (-not $process) {
                continue
            }

            $matchCount = 0
            if ($pidFilePid -eq $candidateId) {
                $matchCount++
            }
            if ($lockPid -eq $candidateId) {
                $matchCount++
            }
            if ($statePid -eq $candidateId) {
                $matchCount++
            }

            [pscustomobject]@{
                Pid = $candidateId
                MatchCount = $matchCount
                Process = $process
            }
        }
    )

    $selectedLiveCandidate = $liveCandidates |
        Sort-Object -Property @{ Expression = 'MatchCount'; Descending = $true }, @{ Expression = 'Pid'; Descending = $false } |
        Select-Object -First 1

    $isRunning = $false
    if ($selectedLiveCandidate) {
        $lockMatches = $lockPid -and ($selectedLiveCandidate.Pid -eq $lockPid)

        $pidMatches = $pidFilePid -and ($selectedLiveCandidate.Pid -eq $pidFilePid)
        $stateMatches = $statePid -and ($selectedLiveCandidate.Pid -eq $statePid)
        $isRunning = $lockMatches -and ($pidMatches -or $stateMatches)
    }

    $isHealthy = $isRunning -and ($stateStatus -in @('idle', 'running'))

    $details = New-Object System.Collections.Generic.List[string]
    if (-not (Test-Path -LiteralPath $script:PidPath)) {
        $details.Add('worker.pid missing')
    }
    elseif (-not $pidFilePid) {
        $details.Add('worker.pid unreadable')
    }

    if (-not (Test-Path -LiteralPath $script:LockPath)) {
        $details.Add('worker.lock missing')
    }
    elseif (-not $lockPid) {
        $details.Add('worker.lock unreadable')
    }

    if (-not (Test-Path -LiteralPath $script:WorkerStatePath)) {
        $details.Add('worker-state.json missing')
    }
    elseif (-not $statePid) {
        $details.Add('worker-state.json has no pid')
    }

    if (-not (Test-Path -LiteralPath $script:HeartbeatPath)) {
        $details.Add('heartbeat.local.json missing')
    }

    if ($stateStatus) {
        $details.Add(('worker state status={0}' -f $stateStatus))
    }

    if ($heartbeatStatus -and $heartbeatStatus -ne $stateStatus) {
        $details.Add(('heartbeat.local.json status={0}' -f $heartbeatStatus))
    }

    if ($stateStatusMessage) {
        $details.Add(('worker status message: {0}' -f $stateStatusMessage))
    }

    if ($selectedLiveCandidate -and -not $isRunning) {
        $details.Add(('live powershell process {0} found, but local worker markers do not agree' -f $selectedLiveCandidate.Pid))
    }
    elseif (-not $selectedLiveCandidate -and @($candidateIds).Count -gt 0) {
        $details.Add('local worker markers point to a non-running process')
    }

    return [pscustomobject]@{
        IsRunning = $isRunning
        IsHealthy = $isHealthy
        HasPidFile = Test-Path -LiteralPath $script:PidPath
        HasLockFile = Test-Path -LiteralPath $script:LockPath
        HasStateFile = Test-Path -LiteralPath $script:WorkerStatePath
        HasHeartbeatFile = Test-Path -LiteralPath $script:HeartbeatPath
        PidFilePid = $pidFilePid
        LockPid = $lockPid
        StatePid = $statePid
        LivePid = if ($selectedLiveCandidate) { $selectedLiveCandidate.Pid } else { $null }
        ProcessName = if ($selectedLiveCandidate) { $selectedLiveCandidate.Process.ProcessName } else { $null }
        StateStatus = $stateStatus
        StateStatusMessage = $stateStatusMessage
        StateLastStage = $stateLastStage
        HeartbeatStatus = $heartbeatStatus
        Details = @($details)
    }
}

function Remove-StaleLocalArtifacts {
    $removedPaths = New-Object System.Collections.Generic.List[string]

    foreach ($path in @($script:PidPath, $script:LockPath)) {
        if (Test-Path -LiteralPath $path) {
            Remove-Item -LiteralPath $path -Force
            $removedPaths.Add($path)
        }
    }

    return @($removedPaths)
}

function Confirm-WorkerStartup {
    param(
        [Parameter(Mandatory = $true)]
        [datetime]$LaunchStartedAt,
        [AllowNull()]
        [datetime]$PreviousStateWriteUtc,
        [AllowNull()]
        [datetime]$PreviousHeartbeatWriteUtc
    )

    $deadline = (Get-Date).AddSeconds(20)

    while ((Get-Date) -lt $deadline) {
        Start-Sleep -Seconds 1

        $status = Get-WorkerStatus
        $stateSnapshot = Get-JsonTimestampSnapshot -Path $script:WorkerStatePath -TimestampProperty 'updated_at' -PidProperty 'pid'
        $heartbeatSnapshot = Get-JsonTimestampSnapshot -Path $script:HeartbeatPath -TimestampProperty 'updated_at' -PidProperty ''

        $stateChanged = $false
        if ($stateSnapshot.Exists) {
            if ($null -eq $PreviousStateWriteUtc) {
                $stateChanged = $true
            }
            elseif ($stateSnapshot.LastWriteTimeUtc -gt $PreviousStateWriteUtc) {
                $stateChanged = $true
            }
            elseif ($stateSnapshot.UpdatedAt -and $stateSnapshot.UpdatedAt.UtcDateTime -ge $LaunchStartedAt.ToUniversalTime()) {
                $stateChanged = $true
            }
        }

        $heartbeatChanged = $false
        if ($heartbeatSnapshot.Exists) {
            if ($null -eq $PreviousHeartbeatWriteUtc) {
                $heartbeatChanged = $true
            }
            elseif ($heartbeatSnapshot.LastWriteTimeUtc -gt $PreviousHeartbeatWriteUtc) {
                $heartbeatChanged = $true
            }
            elseif ($heartbeatSnapshot.UpdatedAt -and $heartbeatSnapshot.UpdatedAt.UtcDateTime -ge $LaunchStartedAt.ToUniversalTime()) {
                $heartbeatChanged = $true
            }
        }

        if ($status.IsHealthy -and $status.HasPidFile -and $status.HasLockFile -and $status.HasStateFile -and $status.HasHeartbeatFile -and $stateChanged -and $heartbeatChanged) {
            return [pscustomobject]@{
                Success = $true
                Status = $status
                StateSnapshot = $stateSnapshot
                HeartbeatSnapshot = $heartbeatSnapshot
            }
        }
    }

    return [pscustomobject]@{
        Success = $false
        Status = Get-WorkerStatus
        StateSnapshot = Get-JsonTimestampSnapshot -Path $script:WorkerStatePath -TimestampProperty 'updated_at' -PidProperty 'pid'
        HeartbeatSnapshot = Get-JsonTimestampSnapshot -Path $script:HeartbeatPath -TimestampProperty 'updated_at' -PidProperty ''
    }
}

