function Test-ProcessRunning {
    param(
        [int]$ProcessId
    )

    if (-not $ProcessId) {
        return $false
    }

    return $null -ne (Get-Process -Id $ProcessId -ErrorAction SilentlyContinue)
}

function Resolve-StaleWorkerArtifacts {
    param(
        [Parameter(Mandatory = $true)]
        [string]$LockPath,
        [Parameter(Mandatory = $true)]
        [string]$PidPath,
        [Parameter(Mandatory = $true)]
        [string]$WorkerStatePath
    )

    $candidateIds = New-Object System.Collections.Generic.List[int]

    if (Test-Path -LiteralPath $LockPath) {
        try {
            $lockData = Get-Content -LiteralPath $LockPath -Raw | ConvertFrom-Json
            $lockPid = [int]$lockData.pid
            if ($lockPid -gt 0 -and $lockPid -notin $candidateIds) {
                $candidateIds.Add($lockPid)
            }
        }
        catch {
        }
    }

    if (Test-Path -LiteralPath $PidPath) {
        $pidValue = (Get-Content -LiteralPath $PidPath -Raw).Trim()
        $parsedPid = 0
        if ([int]::TryParse($pidValue, [ref]$parsedPid) -and $parsedPid -gt 0 -and $parsedPid -notin $candidateIds) {
            $candidateIds.Add($parsedPid)
        }
    }

    if (Test-Path -LiteralPath $WorkerStatePath) {
        try {
            $stateData = Get-Content -LiteralPath $WorkerStatePath -Raw | ConvertFrom-Json
            $statePid = [int]$stateData.pid
            if ($statePid -gt 0 -and $statePid -notin $candidateIds) {
                $candidateIds.Add($statePid)
            }
        }
        catch {
        }
    }

    foreach ($candidateId in $candidateIds) {
        if (Test-ProcessRunning -ProcessId $candidateId) {
            throw "Worker lock already exists and process $candidateId is still running."
        }
    }

    foreach ($path in @($LockPath, $PidPath)) {
        if (Test-Path -LiteralPath $path) {
            Remove-Item -LiteralPath $path -Force
        }
    }
}

