function Format-NullableDate {
    param(
        [AllowNull()]
        [object]$Value
    )

    if ($null -eq $Value) {
        return $null
    }

    if ($Value -is [datetime]) {
        return $Value.ToString('o')
    }

    if ($Value -is [DateTimeOffset]) {
        return $Value.ToString('o')
    }

    return [string]$Value
}

function Normalize-ErrorMessage {
    param(
        [AllowNull()]
        [string]$Message
    )

    if ([string]::IsNullOrWhiteSpace($Message)) {
        return 'Command failed without any diagnostic output.'
    }

    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($line in ($Message -split "(`r`n|`n|`r)")) {
        $trimmed = $line.Trim()
        if (-not $trimmed) {
            continue
        }

        if ($trimmed -match '^From https?://') {
            continue
        }

        if ($trimmed -notin $lines) {
            $lines.Add($trimmed)
        }
    }

    if ($lines.Count -eq 0) {
        return $Message.Trim()
    }

    return ($lines -join ' | ')
}

