function Update-WorkerStatusLocal {
    param(
        [Parameter(Mandatory = $true)]
        [psobject]$Config,
        [Parameter(Mandatory = $true)]
        [string]$Status,
        [Parameter(Mandatory = $true)]
        [string]$Stage,
        [Parameter(Mandatory = $true)]
        [string]$StatusMessage,
        [AllowNull()]
        [string]$CurrentTaskId,
        [int]$InboxTaskCount = 0,
        [AllowNull()]
        [string]$LastError
    )

    $timestamp = Get-Date
    $script:WorkerContext.CurrentStatus = $Status
    $script:WorkerContext.LastStage = $Stage
    $script:WorkerContext.CurrentTaskId = $CurrentTaskId
    $script:WorkerContext.StatusMessage = $StatusMessage
    $script:WorkerContext.LastLocalHeartbeatAt = $timestamp
    $script:WorkerContext.InboxTaskCount = $InboxTaskCount

    if ($PSBoundParameters.ContainsKey('LastError')) {
        $script:WorkerContext.LastError = $LastError
    }
    elseif ($Status -notin @('auth-error', 'sync-error')) {
        $script:WorkerContext.LastError = $null
    }

    $heartbeat = [ordered]@{
        worker_id = $script:WorkerContext.WorkerId
        pid = $PID
        updated_at = $timestamp.ToString('o')
        status = $Status
        status_message = $StatusMessage
        last_stage = $Stage
        last_error = $script:WorkerContext.LastError
        current_task_id = $CurrentTaskId
        branch = $Config.branch
        repo_full_name = $Config.repo_full_name
        mode = 'idle-poller-v1'
        inbox_task_count = $InboxTaskCount
