function Invoke-StepWithRetry {
    param(
        [Parameter(Mandatory = $true)]
        [string]$Stage,
        [Parameter(Mandatory = $true)]
        [scriptblock]$Action,
        [Parameter(Mandatory = $true)]
        [psobject]$Config
    )

    $retryCount = Get-RetryCount -Config $Config
    $retryDelaySeconds = Get-RetryDelaySeconds -Config $Config
    $attempt = 0

    while ($attempt -lt $retryCount) {
        $attempt++
        Write-WorkerStageLog -Stage $Stage -Message ("attempt {0}/{1}." -f $attempt, $retryCount)

        try {
            $result = & $Action
            return [pscustomobject]@{
                Success = $true
                Stage = $Stage
                Attempt = $attempt
                Result = $result
            }
        }
        catch {
            $failure = New-GitFailureResult -Stage $Stage -Message $_.Exception.Message
            Write-WorkerStageLog -Stage $Stage -Message ("attempt {0}/{1} failed with {2}: {3}" -f $attempt, $retryCount, $failure.Status, $failure.Message) -Level 'ERROR'
            if ($attempt -ge $retryCount) {
                return $failure
            }

            Write-WorkerStageLog -Stage $Stage -Message ("retrying in {0} second(s)." -f $retryDelaySeconds) -Level 'WARN'
            Start-Sleep -Seconds $retryDelaySeconds
        }
    }
}

function Invoke-SyncPreflight {
    param(
        [Parameter(Mandatory = $true)]
        [psobject]$Config
    )

    Write-WorkerStageLog -Stage 'preflight' -Message 'verifying transport repository.'
    try {
        Ensure-Clone -Config $Config | Out-Null
    }
    catch {
        return New-GitFailureResult -Stage 'preflight' -Message $_.Exception.Message
    }

    $fetchResult = Invoke-StepWithRetry -Stage 'fetch' -Action { Fetch-Branch -Config $Config | Out-Null } -Config $Config
    if (-not $fetchResult.Success) {
        return $fetchResult
    }

    $pullResult = Invoke-StepWithRetry -Stage 'pull' -Action { Pull-Branch -Config $Config | Out-Null } -Config $Config
    if (-not $pullResult.Success) {
        return $pullResult
    }

    $script:WorkerContext.LastSuccessfulSyncAt = Get-Date
    return [pscustomobject]@{
        Success = $true
        Stage = 'pull'
        Status = 'ok'
        Message = 'Transport preflight completed successfully.'
    }
}

