function Publish-TransportChanges {
    param(
        [Parameter(Mandatory = $true)]
        [psobject]$Config,
        [Parameter(Mandatory = $true)]
        [string]$Message,
        [Parameter(Mandatory = $true)]
        [string[]]$Paths,
        [Parameter(Mandatory = $true)]
        [string]$Stage
    )

    Write-WorkerStageLog -Stage $Stage -Message ("publishing transport changes: {0}" -f $Message)

    try {
        $committed = Commit-If-Needed -Config $Config -Message $Message -Paths $Paths
    }
    catch {
        return New-GitFailureResult -Stage $Stage -Message $_.Exception.Message
    }

    if (-not $committed) {
        return [pscustomobject]@{
            Success = $true
            Stage = $Stage
            Status = 'ok'
            Committed = $false
        }
    }

    $pushResult = Invoke-StepWithRetry -Stage $Stage -Action { Push-Branch -Config $Config | Out-Null } -Config $Config
    if (-not $pushResult.Success) {
        return $pushResult
    }

    return [pscustomobject]@{
        Success = $true
        Stage = $Stage
        Status = 'ok'
        Committed = $true
    }
}

