function Get-SleepSeconds {
    param(
        [Parameter(Mandatory = $true)]
        [psobject]$Config
    )

    $jitterLimit = [Math]::Max(0, [int]$Config.timing.jitter_seconds)
    $jitter = if ($jitterLimit -gt 0) { Get-Random -Minimum 0 -Maximum ($jitterLimit + 1) } else { 0 }
    return [int]$Config.timing.poll_seconds + $jitter
}

